package org.slavicmyths.quest185;
import java.util.*;
import java.util.function.Predicate;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.saveddata.SavedData;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.state.BlockState;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.level.BlockEvent;
/** Radius-four connected selection, persisted reservations, 60-tick bounded work. */
public final class CleansingTasks extends SavedData {
 static final class Task{UUID owner;String name="Quest185";long start,next;int total,done;final ArrayDeque<BlockPos> cells=new ArrayDeque<>();final Map<BlockPos,BlockState> expected=new HashMap<>();}
 private final ArrayDeque<Task> tasks=new ArrayDeque<>();private final Set<BlockPos> reserved=new HashSet<>();
 public static CleansingTasks get(ServerLevel w){return w.getDataStorage().computeIfAbsent(new Factory<>(CleansingTasks::new,(n,r)->load(n,w)),"slavicmyths_cleansing185");}
 public static List<BlockPos> connected(BlockPos center,Predicate<BlockPos> infected,Predicate<BlockPos> eligible){if(!infected.test(center)||!eligible.test(center))return List.of();var seen=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();var result=new ArrayList<BlockPos>();queue.add(center.immutable());seen.add(center.immutable());while(!queue.isEmpty()){var p=queue.removeFirst();if(!infected.test(p))continue;if(eligible.test(p))result.add(p);for(var d:Direction.values()){var next=p.relative(d);if(next.distSqr(center)<=16&&seen.add(next))queue.add(next);}}result.sort(Comparator.<BlockPos>comparingDouble(p->p.distSqr(center)).thenComparingInt(BlockPos::getY).thenComparingInt(BlockPos::getX).thenComparingInt(BlockPos::getZ));return List.copyOf(result.subList(0,Math.min(9,result.size())));}
 private static boolean matches(BlockState expected,BlockState current){return current.equals(expected)||expected.is(org.slavicmyths.mor.MorBlocks.BLOCKS.get("grass_block").get())&&current.is(org.slavicmyths.mor.MorBlocks.BLOCKS.get("dirt").get());}
 public static long due(long start,int index,int count){return start+(count<=1?60:5+55L*index/(count-1));}
 public static boolean permitted(ServerPlayer p,BlockPos pos,BlockState state){var w=p.serverLevel();return w.hasChunkAt(pos)&&w.getWorldBorder().isWithinBounds(pos)&&!p.isSpectator()&&p.mayBuild()&&p.mayInteract(w,pos)&&w.mayInteract(p,pos)&&w.getBlockEntity(pos)==null&&!NeoForge.EVENT_BUS.post(new BlockEvent.BreakEvent(w,pos,state,p)).isCanceled();}
 public boolean start(ServerPlayer p,BlockPos center,Direction face,ItemStack powder){var w=p.serverLevel();if(tasks.size()>=8||powder.isEmpty()||!powder.is(Quest185Content.POWDER.get()))return false;var positions=connected(center,pos->w.hasChunkAt(pos)&&org.slavicmyths.mor.MorBlocks.index(w.getBlockState(pos))>=0,pos->!reserved.contains(pos)&&permitted(p,pos,w.getBlockState(pos))&&Quest185Origins.original(w,pos,w.getBlockState(pos))!=null);if(positions.isEmpty()){p.displayClientMessage(Quest185Story.text("nothing_to_cleanse"),true);return false;}var t=new Task();t.owner=p.getUUID();t.name=p.getGameProfile().getName();t.start=w.getGameTime();t.total=positions.size();t.next=due(t.start,0,t.total);for(var pos:positions){t.cells.add(pos);t.expected.put(pos,w.getBlockState(pos));}if(!p.isCreative())powder.shrink(1);reserved.addAll(t.cells);tasks.add(t);setDirty();w.playSound(null,center,Quest185Content.SOUNDS.get("purify").get(),net.minecraft.sounds.SoundSource.PLAYERS,.55f,1);w.sendParticles(Quest185Content.PURIFY.get(),center.getX()+.5,center.getY()+1,center.getZ()+.5,5,.3,.2,.3,.01);p.displayClientMessage(Quest185Story.text("cleansing_started"),true);return true;}
 public int activeTasks(){return tasks.size();}
 public void tick(ServerLevel w){int budget=8;for(var it=tasks.iterator();it.hasNext()&&budget>0;){var t=it.next();if(t.cells.isEmpty()){it.remove();setDirty();continue;}if(w.getGameTime()<t.next)continue;var pos=t.cells.peekFirst();if(!w.hasChunkAt(pos)){t.next=w.getGameTime()+20;setDirty();continue;}t.cells.removeFirst();reserved.remove(pos);budget--;var current=w.getBlockState(pos);if(matches(t.expected.get(pos),current)){var original=Quest185Origins.original(w,pos,current);var player=w.getServer().getPlayerList().getPlayer(t.owner);if(player==null||player.serverLevel()!=w)player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(w,new com.mojang.authlib.GameProfile(t.owner,t.name));var lessons=CleansingLessons.get(w);var tutorialOwner=lessons.tutorialOwner(w,pos);if(original!=null&&permitted(player,pos,current)&&current.equals(w.getBlockState(pos))&&w.setBlock(pos,original,3)){Quest185Origins.remove(w,pos);CleansedLand.mark(w,pos,original);lessons.restored(w,pos,t.owner,tutorialOwner);for(var nearby:w.getEntitiesOfClass(ServerPlayer.class,new net.minecraft.world.phys.AABB(pos).inflate(3)))org.slavicmyths.mor.MorBlockExposure.clearCleansed(nearby);w.sendParticles(Quest185Content.PURIFY.get(),pos.getX()+.5,pos.getY()+.6,pos.getZ()+.5,3,.3,.3,.3,.01);w.sendParticles(Quest185Content.GREEN.get(),pos.getX()+.5,pos.getY()+.8,pos.getZ()+.5,2,.2,.2,.2,.01);if(t.done==t.total-1)w.playSound(null,pos,Quest185Content.SOUNDS.get("purify").get(),net.minecraft.sounds.SoundSource.PLAYERS,.35f,1.12f);}}t.done++;t.next=due(t.start,t.done,t.total);setDirty();}}
 @Override public CompoundTag save(CompoundTag n,net.minecraft.core.HolderLookup.Provider r){var list=new ListTag();for(var t:tasks){var tag=new CompoundTag();tag.putUUID("Owner",t.owner);tag.putString("Name",t.name);tag.putLong("Next",t.next);tag.putLong("Start",t.start);tag.putInt("Total",t.total);tag.putInt("Done",t.done);var cells=new ListTag();for(var pos:t.cells){var c=new CompoundTag();c.putLong("Pos",pos.asLong());c.put("Expected",NbtUtils.writeBlockState(t.expected.get(pos)));cells.add(c);}tag.put("Cells",cells);list.add(tag);}n.put("Tasks",list);return n;}
 public static CleansingTasks load(CompoundTag n,ServerLevel w){var d=new CleansingTasks();for(var raw:n.getList("Tasks",10)){if(d.tasks.size()>=32)break;var tag=(CompoundTag)raw;if(!tag.hasUUID("Owner"))continue;var t=new Task();t.owner=tag.getUUID("Owner");t.name=tag.getString("Name").isEmpty()?"Quest185":tag.getString("Name");t.next=tag.getLong("Next");t.start=tag.contains("Start")?tag.getLong("Start"):w.getGameTime();t.total=Math.clamp(tag.getInt("Total"),1,9);t.done=Math.clamp(tag.getInt("Done"),0,9);for(var rawCell:tag.getList("Cells",10)){if(t.cells.size()>=9)break;var c=(CompoundTag)rawCell;var pos=BlockPos.of(c.getLong("Pos"));if(!d.reserved.add(pos))continue;t.cells.add(pos);t.expected.put(pos,NbtUtils.readBlockState(w.holderLookup(net.minecraft.core.registries.Registries.BLOCK),c.getCompound("Expected")));}d.tasks.add(t);}return d;}
}
